import { Annotation, StateGraph, START, END, MemorySaver } from "@langchain/langgraph";
const State = Annotation.Root({
  ticket: Annotation(),
  category: Annotation(),
  draft: Annotation(),
});
const graph = new StateGraph(State)
  .addNode("triage", triageFn)     // (state) => ({ category })
  .addNode("draft", draftFn)       // (state) => ({ draft })
  .addEdge(START, "triage")
  .addConditionalEdges("triage", (s) => (s.category === "other" ? "human" : "draft"))
  .addNode("human", humanFn)
  .addEdge("draft", END)
  .addEdge("human", END)
  .compile({ checkpointer: new MemorySaver() });
