function runGraph(nodes, edges, initial) {
  let state = { ...initial };
  let current = '__start__';
  const trace = [];
  let steps = 0;
  while (current !== '__end__' && steps++ < 20) {
    const edge = edges[current];
    const next = typeof edge === 'function' ? edge(state) : edge;
    if (next === '__end__') { trace.push(current + ' -> __end__'); break; }
    Object.assign(state, nodes[next](state));
    trace.push(current + ' -> ' + next);
    current = next;
  }
  return { state, trace };
}
const nodes = {
  triage: (s) => ({ category: /late|arrived/i.test(s.ticket) ? 'shipping' : 'other' }),
  draft: (s) => ({ draft: 'Update on your ' + s.category + ' issue: ' + s.ticket }),
  human: (s) => ({ draft: 'ESCALATED: ' + s.ticket }),
};
const edges = {
  __start__: 'triage',
  triage: (s) => (s.category === 'other' ? 'human' : 'draft'),
  draft: '__end__',
  human: '__end__',
};
const r = runGraph(nodes, edges, { ticket: 'My sneakers never arrived.' });
console.log(r.trace.join(' | '));
console.log(JSON.stringify(r.state));

